{"command":"cat << 'EOF' > main.go
package main

import (
	"context"
	"crypto/tls"
	"encoding/csv"
	"encoding/json"
	"fmt"
	"io"
	"math"
	"net/http"
	"net/http/httptrace"
	"os"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
)

type Options struct {
	N                int
	C                int
	Q                float64
	Duration         time.Duration
	Output           string
	OutputFormat     string
	Method           string
	Body             string
	Headers          []string
	DisableKeepalive bool
	URL              string
}

func parseArgs() Options {
	opts := Options{
		N:            200,
		C:            50,
		OutputFormat: "text",
		Method:       "GET",
	}

	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "-h" || arg == "--help" {
			b, _ := os.ReadFile("help.txt")
			fmt.Print(string(b))
			os.Exit(0)
		}
		if arg == "-V" || arg == "--version" {
			fmt.Println("oha 1.12.1")
			os.Exit(0)
		}
		if arg == "-n" && i+1 < len(args) {
			opts.N, _ = strconv.Atoi(args[i+1])
			i++
		} else if arg == "-c" && i+1 < len(args) {
			opts.C, _ = strconv.Atoi(args[i+1])
			i++
		} else if arg == "-q" && i+1 < len(args) {
			opts.Q, _ = strconv.ParseFloat(args[i+1], 64)
			i++
		} else if arg == "-z" && i+1 < len(args) {
			opts.Duration, _ = time.ParseDuration(args[i+1])
			i++
		} else if arg == "-o" && i+1 < len(args) {
			opts.Output = args[i+1]
			i++
		} else if arg == "--output-format" && i+1 < len(args) {
			opts.OutputFormat = args[i+1]
			i++
		} else if arg == "-m" && i+1 < len(args) {
			opts.Method = args[i+1]
			i++
		} else if arg == "-d" && i+1 < len(args) {
			opts.Body = args[i+1]
			i++
		} else if arg == "-H" && i+1 < len(args) {
			opts.Headers = append(opts.Headers, args[i+1])
			i++
		} else if arg == "--disable-keepalive" {
			opts.DisableKeepalive = true
		} else if arg == "--no-tui" {
			// ignore
		} else if strings.HasPrefix(arg, "-") {
			if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") && !strings.HasPrefix(args[i+1], "http") {
				i++
			}
		} else {
			if strings.HasPrefix(arg, "http") {
				opts.URL = arg
			}
		}
	}
	return opts
}

type RequestResult struct {
	ReqStart      float64
	DnsLookup     float64
	DnsDialup     float64
	ResponseDelay float64
	Duration      float64
	Bytes         int64
	Status        int
	Error         error
}

func main() {
	opts := parseArgs()
	if opts.URL == "" {
		os.Exit(1)
	}

	client := &http.Client{
		Transport: &http.Transport{
			DisableKeepAlives: opts.DisableKeepalive,
			TLSClientConfig:   &tls.Config{InsecureSkipVerify: true},
		},
		Timeout: 0,
	}

	var wg sync.WaitGroup
	var mu sync.Mutex
	var results []RequestResult

	start := time.Now()

	var ticker *time.Ticker
	if opts.Q > 0 {
		ticker = time.NewTicker(time.Duration(float64(time.Second) / opts.Q))
	}

	ctx, cancel := context.WithCancel(context.Background())
	if opts.Duration > 0 {
		go func() {
			time.Sleep(opts.Duration)
			cancel()
		}()
	}

	work := make(chan struct{})

	go func() {
		if opts.Duration > 0 {
			for {
				select {
				case <-ctx.Done():
					close(work)
					return
				default:
					if ticker != nil {
						<-ticker.C
					}
					work <- struct{}{}
				}
			}
		} else {
			for i := 0; i < opts.N; i++ {
				if ticker != nil {
					<-ticker.C
				}
				work <- struct{}{}
			}
			close(work)
		}
	}()

	for i := 0; i < opts.C; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for range work {
				reqStart := time.Now()
				var dnsStart, dnsDone, connStart, connDone, gotFirstByte time.Time
				trace := &httptrace.ClientTrace{
					DNSStart:             func(_ httptrace.DNSStartInfo) { dnsStart = time.Now() },
					DNSDone:              func(_ httptrace.DNSDoneInfo) { dnsDone = time.Now() },
					ConnectStart:         func(_, _ string) { connStart = time.Now() },
					ConnectDone:          func(_, _ string, _ error) { connDone = time.Now() },
					GotFirstResponseByte: func() { gotFirstByte = time.Now() },
				}
				reqCtx := httptrace.WithClientTrace(ctx, trace)

				var bodyReader io.Reader
				if opts.Body != "" {
					bodyReader = strings.NewReader(opts.Body)
				}

				req, err := http.NewRequestWithContext(reqCtx, opts.Method, opts.URL, bodyReader)
				if err == nil {
					for _, h := range opts.Headers {
						parts := strings.SplitN(h, ":", 2)
						if len(parts) == 2 {
							req.Header.Add(strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1]))
						}
					}
				}

				resp, err := client.Do(req)

				res := RequestResult{
					ReqStart: time.Since(start).Seconds(),
				}

				if err != nil {
					res.Error = err
				} else {
					res.Status = resp.StatusCode
					if !gotFirstByte.IsZero() {
						res.ResponseDelay = gotFirstByte.Sub(reqStart).Seconds()
					}
					b, _ := io.ReadAll(resp.Body)
					// Estimate header size very roughly
					hSize := len(resp.Status) + 12
					for k, vv := range resp.Header {
						for _, v := range vv {
							hSize += len(k) + len(v) + 4
						}
					}
					res.Bytes = int64(len(b) + hSize)
					resp.Body.Close()
				}
				res.Duration = time.Since(reqStart).Seconds()
				if !dnsDone.IsZero() && !dnsStart.IsZero() {
					res.DnsLookup = dnsDone.Sub(dnsStart).Seconds()
				}
				if !connDone.IsZero() && !dnsStart.IsZero() {
					res.DnsDialup = connDone.Sub(dnsStart).Seconds()
				} else if !connDone.IsZero() && !connStart.IsZero() {
					res.DnsDialup = connDone.Sub(connStart).Seconds()
				}

				mu.Lock()
				results = append(results, res)
				mu.Unlock()
			}
		}()
	}

	wg.Wait()
	totalTime := time.Since(start).Seconds()
	if totalTime == 0 {
		totalTime = 0.000001
	}

	printSummary(opts, results, totalTime)
}

func printSummary(opts Options, results []RequestResult, totalTime float64) {
	// Statistics computation logic to follow...
}
EOF
"}

