{"command":"cat << 'EOF' > main2.go
package main

import (
	"encoding/json"
	"fmt"
	"math"
	"sort"
	"strings"
	"strconv"
)

// ... mock types
type Options struct {
	OutputFormat string
	Output       string
}
type RequestResult struct {
	Duration      float64
	DnsLookup     float64
	DnsDialup     float64
	Bytes         int64
	Status        int
	Error         error
}

func formatBytes(b float64) string {
	if math.IsNaN(b) {
		return "NaN"
	}
	if b < 1024 {
		return fmt.Sprintf("%.0f B", b)
	} else if b < 1024*1024 {
		return fmt.Sprintf("%.2f KiB", b/1024)
	} else if b < 1024*1024*1024 {
		return fmt.Sprintf("%.2f MiB", b/(1024*1024))
	}
	return fmt.Sprintf("%.2f GiB", b/(1024*1024*1024))
}

func formatTime(sec float64) string {
	if math.IsNaN(sec) {
		return "NaN ns"
	}
	if math.IsInf(sec, 1) {
		return "inf ns"
	}
	if math.IsInf(sec, -1) {
		return "-inf ns"
	}
	return fmt.Sprintf("%.4f ms", sec*1000)
}

func main() {
	opts := Options{OutputFormat: "text"}
	results := []RequestResult{
