		} else if arg == "-d" && i+1 < len(args) {
			opts.Body = args[i+1]
			i++
		} else if arg == "-H" && i+1 < len(args) {
			opts.Headers = append(opts.Headers, args[i+1])
			i++
		} else if arg == "--disable-keepalive" {
			opts.DisableKeepalive = true
		} else if arg == "--no-tui" {
			// ignore
		} else if strings.HasPrefix(arg, "-") {
			if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") && !strings.HasPrefix(args[i+1], "http") {
				i++
			}
		} else {
			if strings.HasPrefix(arg, "http") {
				opts.URL = arg
			}
		}
	}
