}

type RequestResult struct {
	ReqStart      float64
	DnsLookup     float64
	DnsDialup     float64
	ResponseDelay float64
	Duration      float64
	Bytes         int64
	Status        int
	Error         error
}

func main() {
	opts := parseArgs()
	if opts.URL == "" {
		os.Exit(1)
	}

	client := &http.Client{
		Transport: &http.Transport{
			DisableKeepAlives: opts.DisableKeepalive,
			TLSClientConfig:   &tls.Config{InsecureSkipVerify: true},
		},
		Timeout: 0,
	}

	var wg sync.WaitGroup
	var mu sync.Mutex
	var results []RequestResult

	start := time.Now()

	var ticker *time.Ticker
	if opts.Q > 0 {
		ticker = time.NewTicker(time.Duration(float64(time.Second) / opts.Q))
	}

	ctx, cancel := context.WithCancel(context.Background())
	if opts.Duration > 0 {
		go func() {
			time.Sleep(opts.Duration)
			cancel()
		}()
	}

	work := make(chan struct{})

	go func() {
		if opts.Duration > 0 {
			for {
				select {
				case <-ctx.Done():
					close(work)
					return
				default:
					if ticker != nil {
						<-ticker.C
					}
					work <- struct{}{}
				}
			}
		} else {
			for i := 0; i < opts.N; i++ {
				if ticker != nil {
					<-ticker.C
				}
				work <- struct{}{}
			}
			close(work)
		}
	}()

	for i := 0; i < opts.C; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for range work {
				reqStart := time.Now()
				var dnsStart, dnsDone, connStart, connDone, gotFirstByte time.Time
				trace := &httptrace.ClientTrace{
					DNSStart:             func(_ httptrace.DNSStartInfo) { dnsStart = time.Now() },
					DNSDone:              func(_ httptrace.DNSDoneInfo) { dnsDone = time.Now() },
					ConnectStart:         func(_, _ string) { connStart = time.Now() },
					ConnectDone:          func(_, _ string, _ error) { connDone = time.Now() },
					GotFirstResponseByte: func() { gotFirstByte = time.Now() },
				}
				reqCtx := httptrace.WithClientTrace(ctx, trace)

				var bodyReader io.Reader
				if opts.Body != "" {
					bodyReader = strings.NewReader(opts.Body)
				}

				req, err := http.NewRequestWithContext(reqCtx, opts.Method, opts.URL, bodyReader)
				if err == nil {
					for _, h := range opts.Headers {
						parts := strings.SplitN(h, ":", 2)
						if len(parts) == 2 {
							req.Header.Add(strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1]))
						}
					}
				}

				resp, err := client.Do(req)

				res := RequestResult{
					ReqStart: time.Since(start).Seconds(),
				}

				if err != nil {
					res.Error = err
				} else {
					res.Status = resp.StatusCode
					if !gotFirstByte.IsZero() {
						res.ResponseDelay = gotFirstByte.Sub(reqStart).Seconds()
					}
					b, _ := io.ReadAll(resp.Body)
					hSize := len(resp.Status) + 12
					for k, vv := range resp.Header {
						for _, v := range vv {
							hSize += len(k) + len(v) + 4
						}
					}
					res.Bytes = int64(len(b) + hSize)
					resp.Body.Close()
				}
				res.Duration = time.Since(reqStart).Seconds()
				if !dnsDone.IsZero() && !dnsStart.IsZero() {
					res.DnsLookup = dnsDone.Sub(dnsStart).Seconds()
				}
				if !connDone.IsZero() && !dnsStart.IsZero() {
					res.DnsDialup = connDone.Sub(dnsStart).Seconds()
				} else if !connDone.IsZero() && !connStart.IsZero() {
					res.DnsDialup = connDone.Sub(connStart).Seconds()
				}

				mu.Lock()
				results = append(results, res)
				mu.Unlock()
			}
		}()
	}

	wg.Wait()
	totalTime := time.Since(start).Seconds()
	if totalTime == 0 {
		totalTime = 0.000001
	}

	printSummary(opts, results, totalTime)
}

func formatBytes(b float64) string {
	if math.IsNaN(b) {
		return "NaN"
	}
	if b < 1024 {
		return fmt.Sprintf("%.0f B", b)
	} else if b < 1024*1024 {
		return fmt.Sprintf("%.2f KiB", b/1024)
	} else if b < 1024*1024*1024 {
		return fmt.Sprintf("%.2f MiB", b/(1024*1024))
	}
	return fmt.Sprintf("%.2f GiB", b/(1024*1024*1024))
}

func formatTime(sec float64) string {
	if math.IsNaN(sec) {
		return "NaN ns"
	}
	if math.IsInf(sec, 1) {
		return "inf ns"
	}
	if math.IsInf(sec, -1) {
		return "-inf ns"
	}
	return fmt.Sprintf("%.4f ms", sec*1000)
}

func printSummary(opts Options, results []RequestResult, totalTime float64) {
	var out io.Writer = os.Stdout
	if opts.Output != "" {
		f, err := os.Create(opts.Output)
		if err == nil {
			defer f.Close()
			out = f
		}
	}

	if opts.OutputFormat == "quiet" {
		return
	}

	if opts.OutputFormat == "csv" {
		w := csv.NewWriter(out)
		w.Write([]string{"request-start", "DNS", "DNS+dialup", "Response-delay", "request-duration", "bytes", "status"})
		for _, r := range results {
			statusStr := strconv.Itoa(r.Status)
			if r.Error != nil {
				statusStr = "0"
			}
			w.Write([]string{
				strconv.FormatFloat(r.ReqStart, 'f', -1, 64),
				strconv.FormatFloat(r.DnsLookup, 'f', -1, 64),
				strconv.FormatFloat(r.DnsDialup, 'f', -1, 64),
				strconv.FormatFloat(r.ResponseDelay, 'f', -1, 64),
				strconv.FormatFloat(r.Duration, 'f', -1, 64),
				strconv.FormatInt(r.Bytes, 10),
				statusStr,
			})
		}
		w.Flush()
		return
	}

	var successCount int
	var totalBytes int64
	var sumDuration float64

	slowest := math.Inf(-1)
	fastest := math.Inf(1)
	var successDurations []float64

	statusCounts := make(map[int]int)
	errorCounts := make(map[string]int)

	var sumDnsLookup, sumDnsDialup float64
	fastestDnsLookup, slowestDnsLookup := math.Inf(1), math.Inf(-1)
	fastestDnsDialup, slowestDnsDialup := math.Inf(1), math.Inf(-1)
	var validDnsLookup, validDnsDialup int

	for _, r := range results {
		if r.Error == nil {
			successCount++
			statusCounts[r.Status]++
			totalBytes += r.Bytes

			successDurations = append(successDurations, r.Duration)
			sumDuration += r.Duration
			if r.Duration > slowest { slowest = r.Duration }
			if r.Duration < fastest { fastest = r.Duration }

			if r.DnsLookup > 0 {
				sumDnsLookup += r.DnsLookup
				if r.DnsLookup > slowestDnsLookup { slowestDnsLookup = r.DnsLookup }
				if r.DnsLookup < fastestDnsLookup { fastestDnsLookup = r.DnsLookup }
				validDnsLookup++
			}
			if r.DnsDialup > 0 {
				sumDnsDialup += r.DnsDialup
				if r.DnsDialup > slowestDnsDialup { slowestDnsDialup = r.DnsDialup }
				if r.DnsDialup < fastestDnsDialup { fastestDnsDialup = r.DnsDialup }
				validDnsDialup++
			}
		} else {
			errorCounts[r.Error.Error()]++
		}
	}

	successRate := float64(0)
	if len(results) > 0 {
		successRate = float64(successCount) / float64(len(results)) * 100
	}
	avg := math.NaN()
	if successCount > 0 {
		avg = sumDuration / float64(successCount)
	} else {
		slowest = math.Inf(-1)
		fastest = math.Inf(1)
	}
	rps := float64(len(results)) / totalTime

	var sizeReq, sizeSec float64
	if successCount > 0 {
		sizeReq = float64(totalBytes) / float64(successCount)
	} else {
		sizeReq = math.NaN()
	}
	sizeSec = float64(totalBytes) / totalTime

	sort.Float64s(successDurations)
	perc := func(p float64) float64 {
		if len(successDurations) == 0 { return math.NaN() }
		idx := int(math.Ceil(float64(len(successDurations))*p/100)) - 1
		if idx < 0 { idx = 0 }
		if idx >= len(successDurations) { idx = len(successDurations) - 1 }
		return successDurations[idx]
	}

	var bucketCounts [11]int
	var bucketKeys [11]float64
	step := float64(0)
	if successCount > 0 {
		step = (slowest - fastest) / 10
		for i := 0; i <= 10; i++ {
			bucketKeys[i] = fastest + float64(i)*step
		}
		for _, d := range successDurations {
			var idx int
			if step == 0 {
				idx = 0
			} else {
				idx = int(math.Floor((d - fastest) / step))
				if idx > 10 { idx = 10 }
			}
			bucketCounts[idx]++
		}
	}

	if opts.OutputFormat == "json" {
		type JSONSummary struct {
			SuccessRate    float64 `json:"successRate"`
			Total          float64 `json:"total"`
			Slowest        float64 `json:"slowest"`
			Fastest        float64 `json:"fastest"`
			Average        float64 `json:"average"`
			RequestsPerSec float64 `json:"requestsPerSec"`
			TotalData      int64   `json:"totalData"`
			SizePerRequest float64 `json:"sizePerRequest"`
			SizePerSec     float64 `json:"sizePerSec"`
		}

		type JSONOutput struct {
			Summary               JSONSummary            `json:"summary"`
			ResponseTimeHistogram map[string]int         `json:"responseTimeHistogram"`
			LatencyPercentiles    map[string]float64     `json:"latencyPercentiles"`
			RPS                   map[string]interface{} `json:"rps"`
			Details               map[string]interface{} `json:"details"`
			StatusCodeDistribution map[string]int        `json:"statusCodeDistribution"`
			ErrorDistribution      map[string]int        `json:"errorDistribution"`
		}

		hist := make(map[string]int)
		for i := 0; i <= 10; i++ {
			if successCount > 0 {
				hist[strconv.FormatFloat(bucketKeys[i], 'f', -1, 64)] = bucketCounts[i]
			}
		}

		percMap := map[string]float64{
			"p10": perc(10), "p25": perc(25), "p50": perc(50), "p75": perc(75),
			"p90": perc(90), "p95": perc(95), "p99": perc(99), "p99.9": perc(99.9), "p99.99": perc(99.99),
		}

		statusDist := make(map[string]int)
		for k, v := range statusCounts {
			statusDist[strconv.Itoa(k)] = v
		}

		errDist := make(map[string]int)
		for k, v := range errorCounts {
			errDist[k] = v
		}

		avgDnsDialup := math.NaN()
		if validDnsDialup > 0 { avgDnsDialup = sumDnsDialup / float64(validDnsDialup) }
		avgDnsLookup := math.NaN()
		if validDnsLookup > 0 { avgDnsLookup = sumDnsLookup / float64(validDnsLookup) }

		jo := JSONOutput{
			Summary: JSONSummary{
				SuccessRate: successRate / 100,
				Total:       totalTime,
				Slowest:     slowest,
				Fastest:     fastest,
				Average:     avg,
				RequestsPerSec: rps,
				TotalData:   totalBytes,
				SizePerRequest: sizeReq,
				SizePerSec:  sizeSec,
			},
			ResponseTimeHistogram: hist,
			LatencyPercentiles:    percMap,
			RPS: map[string]interface{}{
				"mean": rps, "stddev": nil, "max": rps, "min": rps,
				"percentiles": map[string]float64{
					"p10": rps, "p25": rps, "p50": rps, "p75": rps,
					"p90": rps, "p95": rps, "p99": rps, "p99.9": rps, "p99.99": rps,
				},
			},
			Details: map[string]interface{}{
				"DNSDialup": map[string]float64{
					"average": avgDnsDialup, "fastest": fastestDnsDialup, "slowest": slowestDnsDialup,
				},
				"DNSLookup": map[string]float64{
					"average": avgDnsLookup, "fastest": fastestDnsLookup, "slowest": slowestDnsLookup,
				},
			},
			StatusCodeDistribution: statusDist,
			ErrorDistribution:      errDist,
		}

		b, _ := json.MarshalIndent(jo, "", "  ")
		fmt.Fprintln(out, string(b))
		return
	}

	// Text format
	fmt.Fprintf(out, "Summary:\n")
	fmt.Fprintf(out, "  Success rate:\t%.2f%%\n", successRate)
	fmt.Fprintf(out, "  Total:\t%.4f ms\n", totalTime*1000)
	fmt.Fprintf(out, "  Slowest:\t%s\n", formatTime(slowest))
	fmt.Fprintf(out, "  Fastest:\t%s\n", formatTime(fastest))
	fmt.Fprintf(out, "  Average:\t%s\n", formatTime(avg))
	fmt.Fprintf(out, "  Requests/sec:\t%.4f\n\n", rps)

	fmt.Fprintf(out, "  Total data:\t%s\n", formatBytes(float64(totalBytes)))
	if math.IsNaN(sizeReq) {
		fmt.Fprintf(out, "  Size/request:\tNaN\n")
	} else {
		fmt.Fprintf(out, "  Size/request:\t%s\n", formatBytes(sizeReq))
	}
	fmt.Fprintf(out, "  Size/sec:\t%s\n\n", formatBytes(sizeSec))

	fmt.Fprintf(out, "Response time histogram:\n")
	if successCount > 0 {
		maxCount := 0
		for _, c := range bucketCounts {
			if c > maxCount { maxCount = c }
		}
		for i := 0; i <= 10; i++ {
			bars := 0
			if maxCount > 0 {
				bars = int(float64(bucketCounts[i]) * 32 / float64(maxCount))
			}
			barStr := strings.Repeat("■", bars)
			fmt.Fprintf(out, "  %.3f ms [%d] |%s\n", bucketKeys[i]*1000, bucketCounts[i], barStr)
		}
	} else {
		for i := 0; i <= 10; i++ {
			fmt.Fprintf(out, "    NaN ns [0] |\n")
		}
	}

	fmt.Fprintf(out, "\nResponse time distribution:\n")
	fmt.Fprintf(out, "  10.00%% in %s\n", formatTime(perc(10)))
	fmt.Fprintf(out, "  25.00%% in %s\n", formatTime(perc(25)))
	fmt.Fprintf(out, "  50.00%% in %s\n", formatTime(perc(50)))
	fmt.Fprintf(out, "  75.00%% in %s\n", formatTime(perc(75)))
	fmt.Fprintf(out, "  90.00%% in %s\n", formatTime(perc(90)))
	fmt.Fprintf(out, "  95.00%% in %s\n", formatTime(perc(95)))
	fmt.Fprintf(out, "  99.00%% in %s\n", formatTime(perc(99)))
	fmt.Fprintf(out, "  99.90%% in %s\n", formatTime(perc(99.9)))
	fmt.Fprintf(out, "  99.99%% in %s\n\n", formatTime(perc(99.99)))

	fmt.Fprintf(out, "\nDetails (average, fastest, slowest):\n")
	avgDnsDialup := math.NaN()
	if validDnsDialup > 0 { avgDnsDialup = sumDnsDialup / float64(validDnsDialup) }
	fmt.Fprintf(out, "  DNS+dialup:\t%s, %s, %s\n", formatTime(avgDnsDialup), formatTime(fastestDnsDialup), formatTime(slowestDnsDialup))

	avgDnsLookup := math.NaN()
	if validDnsLookup > 0 { avgDnsLookup = sumDnsLookup / float64(validDnsLookup) }
	fmt.Fprintf(out, "  DNS-lookup:\t%s, %s, %s\n\n", formatTime(avgDnsLookup), formatTime(fastestDnsLookup), formatTime(slowestDnsLookup))

	fmt.Fprintf(out, "Status code distribution:\n")
	var statuses []int
	for st := range statusCounts { statuses = append(statuses, st) }
	sort.Ints(statuses)
	for _, st := range statuses {
		fmt.Fprintf(out, "  [%d] %d responses\n", st, statusCounts[st])
	}

	if len(errorCounts) > 0 {
	    fmt.Fprintf(out, "\nError distribution:\n")
	    for errStr, count := range errorCounts {
	        fmt.Fprintf(out, "  [%d] %s\n", count, errStr)
	    }
	}
}
