func parseArgs() Options {
	opts := Options{
		N:            200,
		C:            50,
		OutputFormat: "text",
		Method:       "GET",
	}

	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "-h" || arg == "--help" {
